<script setup lang="ts">
import {KnowledgeMotion} from './knowledge-motion';
import {KnowledgeEdgeLayer} from './knowledge-edge-layer';
import {computed,onBeforeUnmount,onMounted,ref,watch,nextTick} from 'vue';
import {Graph,CircleCombo,register,ExtensionCategory,type CircleComboStyleProps,getExtension} from './knowledge-g6';
class KnowledgeCircle extends CircleCombo {protected getExpandedKeySize(a:Required<CircleComboStyleProps> & {knowledgeRadius?:number;knowledgeX?:number;knowledgeY?:number}):[number,number,number]{const r=Number(a.knowledgeRadius)||36;return [r*2,r*2,0];}getComboPosition(a:Required<CircleComboStyleProps> & {knowledgeRadius?:number;knowledgeX?:number;knowledgeY?:number}):[number,number,number]{return [Number(a.knowledgeX)||0,Number(a.knowledgeY)||0,0];}}
if(!getExtension(ExtensionCategory.COMBO,'knowledge-circle'))register(ExtensionCategory.COMBO,'knowledge-circle',KnowledgeCircle);
import {Button,NativeSelect,OverlayScope,StatusNotice,useHostContext} from '@openclaw-plugins/control-ui-kit';
import {layoutNetwork,validateNetwork,sameNetworkGeometry,groupId,areaColors,type SizeMode} from './knowledge-network';
import type {KnowledgeEntry,KnowledgeEdge} from './knowledge-model';
const props=defineProps<{nodes:KnowledgeEntry[];edges:KnowledgeEdge[];snapshotId?:string}>(),emit=defineEmits<{open:[path:string];select:[path:string];ready:[snapshotId?:string]}>();
const context=useHostContext(),safe=(v:unknown)=>context.value.host.redact(String(v??''));
const root=ref<HTMLElement>(),canvas=ref<HTMLElement>(),selected=ref(''),query=ref(''),area=ref(''),mode=ref<SizeMode>('total'),expanded=ref(new Set<string>()),error=ref(''),maximized=ref(false),fading=ref(false),rendering=ref(false);
const floating=ref(true);let motion:KnowledgeMotion|undefined;let motionStop=Promise.resolve();let motionPreference:MediaQueryList|undefined;
function stopMotion(reset=true){const stopped=motion?.stop(reset);motion=undefined;if(stopped)motionStop=Promise.all([motionStop,stopped]).then(()=>{});return motionStop;}
function startMotion(){void stopMotion(false);if(graph&&canvas.value&&floating.value&&!motionPreference?.matches&&!document.hidden&&lastNetwork){motion=new KnowledgeMotion(graph,canvas.value,lastNetwork,positions=>edgeLayer?.updateMotion(positions));}}
function visibility(){if(document.hidden)void stopMotion();else schedule();}
let rendered=false,renderedEdges=0;
const changes=ref(new Map<string,string>()),removed=ref(0);let lastNodes=new Map<string,string>(),lastSnapshot:string|undefined;
watch(()=>[props.nodes,props.snapshotId] as const,()=>{const next=new Map(props.nodes.map(n=>[n.path,n.contentHash??JSON.stringify(n)]));if(lastSnapshot&&lastSnapshot!==props.snapshotId){changes.value=new Map([...next].filter(([p,h])=>lastNodes.get(p)!==h).map(([p])=>[p,lastNodes.has(p)?'modified':'added']));removed.value=[...lastNodes.keys()].filter(p=>!next.has(p)).length;}lastNodes=next;lastSnapshot=props.snapshotId;},{immediate:true});
let edgeLayer:KnowledgeEdgeLayer|undefined,lastNetwork:ReturnType<typeof layoutNetwork>|undefined,lastPalette='',lastSelected='',geometryNetwork:ReturnType<typeof layoutNetwork>|undefined,lastChanges=new Map<string,string>();
let graph:Graph|undefined,resize:ResizeObserver|undefined,theme:MutationObserver|undefined,alive=true,epoch=0,serial=Promise.resolve();
const filtered=computed(()=>props.nodes.filter(n=>!area.value||n.area===area.value)),areas=computed(()=>[...new Set(props.nodes.map(n=>n.area??'index'))].sort()),current=computed(()=>nodeIndex.value.get(selected.value));
const nodeIndex=computed(()=>new Map(props.nodes.map(n=>[n.path,n])));
const edgeIndex=computed(()=>{const map=new Map<string,KnowledgeEdge[]>();for(const e of props.edges)for(const id of new Set([e.source,e.target])){if(!map.has(id))map.set(id,[]);map.get(id)!.push(e);}return map;});
const searchIndex=computed(()=>props.nodes.map(n=>({n,text:`${n.title} ${n.path} ${n.uid??''}`.toLowerCase()})));
let previous:ReturnType<typeof layoutNetwork>|undefined;
const network=computed(()=>{const next=layoutNetwork(filtered.value,props.edges,expanded.value,mode.value,previous);previous=next;return next;});
const related=computed(()=>edgeIndex.value.get(selected.value)??[]);
const matches=computed(()=>{const q=query.value.toLowerCase(),result:KnowledgeEntry[]=[];for(const {n,text} of searchIndex.value)if(text.includes(q)){result.push(n);if(result.length===30)break;}return result;});
defineExpose({choose});
function expandAll(open:boolean){previous=undefined;rendered=false;expanded.value=open?new Set(props.nodes.map(groupId)):new Set();}
function toggle(id:string){const next=new Set(expanded.value);if(next.has(id))next.delete(id);else next.add(id);expanded.value=next;}
function choose(path:string){selected.value=path;emit('select',path);const n=nodeIndex.value.get(path);if(n){area.value='';if(!expanded.value.has(groupId(n)))expanded.value=new Set([...expanded.value,groupId(n)]);void nextTick(()=>serial.then(()=>graph?.focusElement('doc:'+path,false)));}}
function colors(){const el=canvas.value!,style=getComputedStyle(el);const resolve=(name:string,fallback:string)=>{const probe=document.createElement('span');probe.style.color=`var(${name},${fallback})`;el.append(probe);const value=getComputedStyle(probe).color;probe.remove();return value;};return {text:resolve('--ocp-foreground','#333'),background:resolve('--ocp-background','#fff'),muted:resolve('--ocp-muted','#888'),font:style.fontFamily};}
function schedule(){const stopped=stopMotion();rendering.value=true;const token=++epoch;serial=serial.catch(()=>{}).then(async()=>{await stopped;if(!alive||token!==epoch||!canvas.value)return;try{const rect=canvas.value.getBoundingClientRect();if(!rect.width||!rect.height)return;const palette=colors(),paletteKey=JSON.stringify(palette);
 if(graph&&edgeLayer&&(network.value===lastNetwork||sameNetworkGeometry(lastNetwork,network.value))&&paletteKey===lastPalette){
  const updates=[...new Set([lastSelected,selected.value,...lastChanges.keys(),...changes.value.keys()])].filter(p=>p&&nodeIndex.value.has(p)).map(path=>({id:'doc:'+path,style:{stroke:selected.value===path?palette.text:changes.value.get(path)==='added'?'#278c55':changes.value.has(path)?'#be842b':palette.background,lineWidth:selected.value===path||changes.value.has(path)?3:1,labelText:selected.value===path?safe(nodeIndex.value.get(path)!.title):''}}));
  if(updates.length){graph.updateNodeData(updates);lastSelected=selected.value;lastChanges=new Map(changes.value);await graph.draw();}if(!alive||token!==epoch)return;
  lastNetwork=network.value;edgeLayer.update(geometryNetwork!,palette.muted,selected.value);fading.value=false;rendering.value=false;emit('ready',props.snapshotId);startMotion();return;
 }
 if(graph&&renderedEdges>20000&&network.value.edges.length<renderedEdges/2){edgeLayer?.destroy();edgeLayer=undefined;graph.destroy();graph=undefined;rendered=false;renderedEdges=0;}if(!graph){graph=new Graph({container:canvas.value,width:rect.width,height:rect.height,animation:false,behaviors:['drag-canvas','zoom-canvas',{type:'optimize-viewport-transform',shapes:{node:['key'],combo:['key']},debounce:300}],node:{type:'circle'},edge:{type:'line'},combo:{type:'knowledge-circle'}});graph.on('node:click',e=>{if(!('target' in e)||!e.target||!('id' in e.target))return;const id=String(e.target.id);if(id.startsWith('group:'))toggle(id.slice(6));else if(id.startsWith('doc:'))choose(id.slice(4));});graph.on('combo:click',e=>{if('target' in e&&e.target&&'id' in e.target)toggle(String(e.target.id).slice(6));});}
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!reduced){fading.value=true;await new Promise(r=>setTimeout(r,100));}if(!alive||token!==epoch)return;
 const n=network.value;const dense=n.edges.length>20000;if(dense&&!edgeLayer)edgeLayer=new KnowledgeEdgeLayer(canvas.value,graph);if(!dense&&edgeLayer){edgeLayer.destroy();edgeLayer=undefined;}if(!validateNetwork(n))throw Error('overlapping_layout');lastNetwork=undefined;graph.setData({nodes:[...n.points.map(p=>({id:p.id,combo:'combo:'+p.group,data:{path:p.path},style:{x:p.x,y:p.y,size:p.r*2,fill:areaColors[p.entry.area??'index']??'#8b82ac',stroke:selected.value===p.path?palette.text:changes.value.get(p.path)==='added'?'#278c55':changes.value.has(p.path)?'#be842b':palette.background,lineWidth:selected.value===p.path||changes.value.has(p.path)?3:1,labelText:selected.value===p.path?safe(p.entry.title):'',labelFill:palette.text,labelFontFamily:palette.font,labelPlacement:'bottom' as const}})),...n.groups.filter(g=>!g.expanded).map(g=>({id:'group:'+g.id,style:{x:g.x,y:g.y,size:72,fill:areaColors[g.area]??'#8b82ac',fillOpacity:.22,stroke:areaColors[g.area]??'#8b82ac',labelText:safe(g.label)+'\n'+g.count+' 篇',labelFill:palette.text,labelFontFamily:palette.font}}))],combos:n.groups.filter(g=>g.expanded).map(g=>({id:'combo:'+g.id,style:{x:g.x,y:g.y,knowledgeX:g.x,knowledgeY:g.y,knowledgeRadius:g.r,padding:24,fill:areaColors[g.area]??'#8b82ac',fillOpacity:.06,stroke:areaColors[g.area]??'#8b82ac',lineWidth:1,labelText:safe(g.label)+' · '+g.count,labelFill:palette.text,labelPlacement:'top' as const}})),edges:(dense?[]:n.edges).map((e,i)=>({id:'edge:'+i,source:e.source,target:e.target,style:{stroke:palette.muted,lineWidth:Math.min(3,1+Math.log2(e.count)*.3),strokeOpacity:selected.value?(e.source==='doc:'+selected.value||e.target==='doc:'+selected.value?1:.08):.2,endArrow:n.edges.length<2000||e.source==='doc:'+selected.value||e.target==='doc:'+selected.value}}))});await graph.render();renderedEdges=n.edges.length;if(!alive||token!==epoch)return;if(!rendered){await graph.fitView(undefined,false);rendered=true;}edgeLayer?.update(n,palette.muted,selected.value);lastNetwork=n;geometryNetwork=n;lastChanges=new Map(changes.value);lastPalette=paletteKey;lastSelected=selected.value;canvas.value.dataset.renderedNodes=String(graph.getNodeData().length);canvas.value.dataset.edgeSegments=String(n.edges.length);canvas.value.dataset.edgeRelationships=String(n.edges.reduce((s,e)=>s+e.count,0));fading.value=false;rendering.value=false;error.value='';emit('ready',props.snapshotId);startMotion();}catch{lastNetwork=undefined;if(alive){fading.value=false;rendering.value=false;error.value='图谱绘制失败，可刷新重试；目录和正文仍可使用。';}}});}
async function fullscreen(){if(document.fullscreenElement){await document.exitFullscreen();return;}try{await root.value?.requestFullscreen();}catch{maximized.value=!maximized.value;}}
function key(e:KeyboardEvent){if(e.key==='Escape'&&maximized.value)maximized.value=false;}
watch([network,selected],schedule);watch(()=>props.snapshotId,()=>{selected.value='';});
watch(floating,schedule);
onMounted(()=>{motionPreference=matchMedia('(prefers-reduced-motion: reduce)');motionPreference.addEventListener('change',schedule);document.addEventListener('visibilitychange',visibility);resize=new ResizeObserver(()=>{if(canvas.value&&graph){const r=canvas.value.getBoundingClientRect();if(r.width&&r.height)graph.setSize(r.width,r.height);edgeLayer?.schedule();}else schedule();});if(canvas.value)resize.observe(canvas.value);theme=new MutationObserver(schedule);for(let e:Element|null=root.value??null;e;e=e.parentElement)theme.observe(e,{attributes:true,attributeFilter:['class','style','data-theme']});document.addEventListener('keydown',key);schedule();void nextTick(()=>serial.then(()=>graph?.fitView(undefined,false)));});
onBeforeUnmount(()=>{void stopMotion(false);motionPreference?.removeEventListener('change',schedule);document.removeEventListener('visibilitychange',visibility);alive=false;epoch++;resize?.disconnect();theme?.disconnect();document.removeEventListener('keydown',key);edgeLayer?.destroy();edgeLayer=undefined;graph?.destroy();graph=undefined;});
</script>
<template><section ref="root" class="kb-graph" :class="{maximized}" aria-label="知识库图谱"><OverlayScope><div class="kb-graph-toolbar"><input v-model="query" aria-label="查找图谱文档" placeholder="标题、路径或 UID"/><NativeSelect v-model="area" aria-label="图谱知识区"><option value="">全部知识区</option><option v-for="a in areas" :key="a" :value="a">{{safe(a)}}</option></NativeSelect><NativeSelect v-model="mode" aria-label="节点大小依据"><option value="total">入链＋出链</option><option value="in">被引用数</option><option value="out">引用数</option></NativeSelect><Button variant="outline" size="sm" @click="expandAll(true)">全部展开</Button><Button variant="outline" size="sm" @click="expandAll(false)">全部收起</Button><Button variant="outline" size="sm" @click="graph?.fitView(undefined,false)">适应画布</Button><Button variant="outline" size="sm" aria-label="放大图谱" @click="graph?.zoomBy(1.2,false)">放大</Button><Button variant="outline" size="sm" aria-label="缩小图谱" @click="graph?.zoomBy(.8,false)">缩小</Button><Button variant="outline" size="sm" :aria-pressed="floating" @click="floating=!floating">{{floating?'暂停漂浮':'开启漂浮'}}</Button><Button variant="outline" size="sm" @click="fullscreen">全屏 / 退出</Button><Button v-if="maximized" @click="maximized=false">退出最大化</Button></div><div class="kb-graph-summary">{{nodes.length}} 篇文档 · {{edges.length}} 条关系 · {{network.groups.length}} 个分组<span v-if="changes.size||removed"> · 新增/修改 {{changes.size}}（绿色/琥珀色描边） · 删除 {{removed}}（上一帧淡出）</span> · {{network.edges.length>20000?'拖动时保留全部连线':'拖动时暂隐连线，停下后恢复'}}</div><StatusNotice v-if="error" tone="error">{{error}}<Button @click="schedule">重试</Button></StatusNotice><div v-if="query" class="kb-matches"><Button v-for="n in matches" :key="n.path" variant="ghost" @click="choose(n.path)">{{safe(n.title)}}</Button></div><div class="kb-graph-workspace" :class="{'has-detail':current}"><div ref="canvas" class="kb-network" :data-render-state="rendering?'rendering':'ready'" :class="{fading}" role="img" aria-label="知识图谱画布"/><aside v-if="current" class="kb-graph-detail"><template v-if="current"><h3>{{safe(current.title)}}</h3><p>{{safe(current.path)}}</p><p>入链 {{current.inDegree??0}} · 出链 {{current.outDegree??0}}</p><p v-if="current.featureId">Feature：{{safe(current.featureId)}}（{{current.featureSource==='path'?'目录推导':'元数据'}}）</p><Button @click="emit('open',current.path)">打开文档</Button><h4>相关关系 · {{related.length}}</h4><div class="kb-related"><Button v-for="(e,i) in related" :key="i" variant="ghost" @click="choose(e.source===current.path?e.target:e.source)">{{e.source===current.path?'→':'←'}} {{safe(e.source===current.path?e.target:e.source)}}</Button></div></template><p v-else>选择节点查看详情；点击分组展开或收起。</p></aside></div><details><summary>分组导航</summary><Button v-for="g in network.groups" :key="g.id" variant="ghost" @click="toggle(g.id)">{{g.expanded?'收起':'展开'}} {{safe(g.label)}} · {{g.count}}</Button></details><div class="kb-legend"><span v-for="a in areas" :key="a"><i :style="{background:areaColors[a]??'#8b82ac'}"/>{{safe(a)}}</span></div><slot name="timeline"/><slot name="overlay"/></OverlayScope></section></template>
<style scoped>.kb-graph{background:var(--ocp-background);color:var(--ocp-foreground);min-width:0}.kb-graph:fullscreen,.kb-graph.maximized{padding:20px;width:100%;height:100%;overflow:auto}.kb-graph.maximized{position:fixed;inset:0;z-index:1000}.kb-graph-toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.kb-graph-toolbar input{min-width:0;max-width:100%;padding:8px;border:1px solid var(--ocp-border);background:var(--ocp-background);color:inherit;border-radius:6px}.kb-graph-summary{font-size:12px;color:var(--ocp-muted);margin:12px 0}.kb-graph-workspace{display:grid;grid-template-columns:minmax(0,1fr);gap:12px}.kb-graph-workspace.has-detail{grid-template-columns:minmax(0,1fr) 230px}.kb-network{position:relative;height:560px;min-width:0;border:1px solid var(--ocp-border);border-radius:12px;overflow:hidden;opacity:1;transition:opacity .1s}.kb-network.fading{opacity:0}.kb-graph:fullscreen .kb-network,.kb-graph.maximized .kb-network{height:calc(100vh - 240px)}.kb-graph-detail{font-size:12px;overflow-wrap:anywhere;padding:12px;border:1px solid var(--ocp-border);border-radius:12px}.kb-graph-detail button{white-space:normal;height:auto;text-align:left}.kb-related{max-height:240px;overflow:auto;display:grid}.kb-legend{display:flex;flex-wrap:wrap;gap:16px;font-size:12px;margin:12px 0}.kb-legend i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}.kb-matches{max-height:150px;overflow:auto}.kb-graph-detail details button{display:block}@media(max-width:850px){.kb-graph-workspace.has-detail{grid-template-columns:1fr}.kb-network{height:440px}}@media(prefers-reduced-motion:reduce){.kb-network{transition:none}}
</style>
